function rateLimiter({ windowMs, max, now = Date.now }) {
  const hits = new Map()                            // key -> { start, count }

  return function limiter(req, res, next) {
    const key = req.ip
    const t = now()
    const entry = hits.get(key)

    if (!entry || t - entry.start >= windowMs) {    // new window
      hits.set(key, { start: t, count: 1 })
      return next()
    }
    entry.count++
    if (entry.count > max) {
      const retryAfter = Math.ceil((entry.start + windowMs - t) / 1000)
      return res.status(429).json({ error: 'Too many requests', retryAfter })
    }
    next()
  }
}

// --- simulate requests with a fake clock ---
let clock = 0
const limiter = rateLimiter({ windowMs: 10_000, max: 3, now: () => clock })

function fakeRes() {
  return {
    status(code) { this.code = code; return this },
    json(body) { console.log(`  -> ${this.code}`, JSON.stringify(body)) },
  }
}

function hit(label, ip = '1.1.1.1') {
  console.log(`t=${clock}ms ${label}`)
  limiter({ ip }, fakeRes(), () => console.log('  -> allowed'))
}

hit('request 1')
hit('request 2')
hit('request 3')
hit('request 4 (over the limit)')
hit('other client', '2.2.2.2')
clock = 4000
hit('request 5 (still same window)')
clock = 10000
hit('request 6 (new window)')

// asyncHandler (needed in Express 4, harmless in 5)
export const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next)

// compose: run middleware one after another (the idea behind app.use)
export function compose(middlewares) {
  return function run(req, res, done = () => {}) {
    let index = -1
    function dispatch(i, err) {
      if (err) return done(err)                       // next(err) skips everything left
      if (i <= index) throw new Error('next() called multiple times')
      index = i
      const fn = middlewares[i]
      if (!fn) return done()
      try {
        fn(req, res, (e) => dispatch(i + 1, e))
      } catch (e) {
        done(e)                                       // thrown errors become next(err)
      }
    }
    dispatch(0)
  }
}

