// ## fastify.js
import Fastify from 'fastify'
const app = Fastify()
app.get('/users/:id', async (request) => ({ id: request.params.id, q: request.query }))
app.post('/users', {
  schema: { body: { type: 'object', required: ['name'], properties: { name: { type: 'string', minLength: 2 } } } },
}, async (request, reply) => reply.code(201).send({ created: request.body.name }))   // invalid body -> automatic 400
await app.listen({ port: 3000 })

// ## koa.js
import Koa from 'koa'
import Router from '@koa/router'
const app = new Koa()
const router = new Router()
router.get('/users/:id', (ctx) => { ctx.body = { id: ctx.params.id, q: ctx.query } })

app.use(async (ctx, next) => {          // onion: code before AND after next()
  const start = Date.now()
  await next()
  ctx.set('X-Response-Time', `${Date.now() - start}ms`)
})
app.use(router.routes())
app.listen(3000)

